import { randomUUID } from "node:crypto";
import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
import { extname, resolve, sep } from "node:path";
import type { FileStorage } from "./file-storage";

/**
 * Development adapter that keeps documents outside the web root. Keys are
 * relative paths generated by the adapter; user-supplied names never reach the
 * filesystem, which also rules out path traversal.
 */
export class LocalFileStorage implements FileStorage {
  constructor(private readonly rootDir: string) {}

  async save(input: { data: Buffer; originalName: string; mimeType: string }): Promise<{ key: string }> {
    const now = new Date();
    const folder = `${now.getUTCFullYear()}/${String(now.getUTCMonth() + 1).padStart(2, "0")}`;
    const extension = this.safeExtension(input.originalName);
    const key = `${folder}/${randomUUID()}${extension}`;
    const target = this.resolveKey(key);
    await mkdir(resolve(target, ".."), { recursive: true });
    await writeFile(target, input.data);
    return { key };
  }

  async read(key: string): Promise<Buffer> {
    return readFile(this.resolveKey(key));
  }

  async remove(key: string): Promise<void> {
    await rm(this.resolveKey(key), { force: true });
  }

  private resolveKey(key: string): string {
    const target = resolve(this.rootDir, key);
    const root = resolve(this.rootDir);
    if (target !== root && !target.startsWith(`${root}${sep}`)) {
      throw new Error("Resolved storage key escapes the storage root");
    }
    return target;
  }

  private safeExtension(originalName: string): string {
    const extension = extname(originalName).toLowerCase();
    return /^\.[a-z0-9]{1,10}$/.test(extension) ? extension : "";
  }
}
